import{_ as e,c as a,o as l,af as r}from"./chunks/framework.4G89wRmb.js";const g=JSON.parse('{"title":"南武最高人民委员会","description":"","frontmatter":{},"headers":[],"relativePath":"databank/settings/main/supreme_peoples_committee.md","filePath":"databank/settings/main/supreme_peoples_committee.md"}'),n={name:"databank/settings/main/supreme_peoples_committee.md"};function s(h,t,i,o,m,d){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="南武最高人民委员会" tabindex="-1">南武最高人民委员会 <a class="header-anchor" href="#南武最高人民委员会" aria-label="Permalink to “南武最高人民委员会”">​</a></h1><p><strong>南武最高人民委员会</strong>（Supreme People&#39;s Committee of Nambu），是<a href="./nambu_rengoist_party.html">南武联合党</a>和<a href="./nambu_commonwealth.html">南武集团</a>的最高领导机构，也是<a href="./rengoist_republic_of_nambu.html">联合主义南武共和国</a>的最高决策核心。</p><h2 id="基本情报" tabindex="-1">基本情报 <a class="header-anchor" href="#基本情报" aria-label="Permalink to “基本情报”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>性质</strong></td><td style="text-align:left;">党和集团的最高领导机构</td></tr><tr><td style="text-align:left;"><strong>地位</strong></td><td style="text-align:left;">国家的最高决策核心</td></tr><tr><td style="text-align:left;"><strong>领导职位</strong></td><td style="text-align:left;">总书记</td></tr><tr><td style="text-align:left;"><strong>任期</strong></td><td style="text-align:left;">16年（对应两届<a href="./nambu_congress.html">全南武进步者大会</a>）</td></tr><tr><td style="text-align:left;"><strong>现任总书记</strong></td><td style="text-align:left;"><a href="./../people/kawai_hachimi.html">川伊八海</a>（第五、六届）</td></tr><tr><td style="text-align:left;"><strong>核心制度</strong></td><td style="text-align:left;"><a href="./comprehensive_leadership.html">全面领导制</a></td></tr></tbody></table><h2 id="性质与职能" tabindex="-1">性质与职能 <a class="header-anchor" href="#性质与职能" aria-label="Permalink to “性质与职能”">​</a></h2><p>最高人民委员会是<a href="./comprehensive_leadership.html">全面领导制</a>的最高体现，由党的数位核心领导人组成，负责对党、国家、<a href="./nambu_commonwealth.html">南武集团</a>及<a href="./peoples_defense_army.html">南武人民防卫军</a>等所有机构实施统一和绝对的领导。</p><p>其核心职能包括：</p><ul><li>制定国家在政治、经济、军事等所有领域的根本战略和方针。</li><li>领导和管理<a href="./nambu_commonwealth.html">南武集团</a>，审批国家级经济计划。</li><li>决定<a href="./rengoism.html">联合主义</a>的理论发展方向，领导意识形态工作。</li><li>指导并监督<a href="./central_government.html">南武中央人民政府</a>和<a href="./nambu_congress.html">全南武进步者大会</a>的工作。</li><li>通过党的军事机构，对<a href="./peoples_defense_army.html">南武人民防卫军</a>实施最高军事领导。</li></ul><h2 id="运作与换届" tabindex="-1">运作与换届 <a class="header-anchor" href="#运作与换届" aria-label="Permalink to “运作与换届”">​</a></h2><p>委员会每年定期召开全体会议，讨论和决定国家的重大问题。</p><p>委员会每十六年换届一次，与其领导人（总书记）的任期同步，该周期对应两届<a href="./nambu_congress.html">“八年会”</a>。</p><h2 id="历代委员会与总书记" tabindex="-1">历代委员会与总书记 <a class="header-anchor" href="#历代委员会与总书记" aria-label="Permalink to “历代委员会与总书记”">​</a></h2><p>最高人民委员会的每一代领导集体都在<a href="./rengoism.html">联合主义</a>的理论基础上不断发展，形成了清晰的继承脉络。</p><table tabindex="0"><thead><tr><th style="text-align:left;">届数</th><th style="text-align:left;">总书记</th><th style="text-align:left;">主要理论贡献 / 路线</th></tr></thead><tbody><tr><td style="text-align:left;">第一、二届</td><td style="text-align:left;"><a href="./../people/nambu_kojun.html">南武香淳</a></td><td style="text-align:left;"><strong><a href="./rengoism.html">香淳思想</a></strong>：奠定共和国<a href="./rengoism.html">联合主义</a>理论基础。</td></tr><tr><td style="text-align:left;">第三、四届</td><td style="text-align:left;"><a href="./../people/tokishi_kisetsu.html">户岸希节</a></td><td style="text-align:left;"><strong><a href="./kisetsu_line.html">希节路线</a></strong>：确立<a href="./nambu_commonwealth.html">南武集团</a>经济模式。</td></tr><tr><td style="text-align:left;">第五、六届</td><td style="text-align:left;"><a href="./../people/kawai_hachimi.html">川伊八海</a></td><td style="text-align:left;"><strong><a href="./hachimi_theory.html">八海理论</a></strong>：开启<a href="./cyber_utopia.html">赛博乌托邦</a>建设时代。</td></tr></tbody></table>',14)])])}const p=e(n,[["render",s]]);export{g as __pageData,p as default};
